#!/usr/bin/env node
/**
 * scripts/vercel-module-output.mjs — makes a Git-connected Vercel project honour deploy/modules/<id>/vercel.json.
 * Vercel only reads a root vercel.json, but the per-module rewrites (/login, /register, SPA fallback) and security headers
 * live in deploy/modules/<id>/vercel.json (generated by gen-module-deploy.mjs). After `build:module`, this copies the
 * module's dist into .vercel/output/static and writes .vercel/output/config.json (Build Output API v3) from that file.
 *   VITE_MODULE=ryft node scripts/vercel-module-output.mjs
 */
import { cpSync, existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");

export function toConfig(vercelJson) {
  const routes = [];
  for (const h of vercelJson.headers ?? []) {
    routes.push({ src: `^${h.source}$`, headers: Object.fromEntries(h.headers.map((x) => [x.key, x.value])), continue: true });
  }
  routes.push({ handle: "filesystem" });
  for (const r of vercelJson.rewrites ?? []) routes.push({ src: `^${r.source}$`, dest: r.destination });
  return { version: 3, routes };
}

export function run(id, root = ROOT) {
  if (!/^[a-z]+$/.test(id ?? "")) throw new Error(`VITE_MODULE is required (got "${id}")`);
  const dist = join(root, "artifacts/ayzen/dist/modules", id);
  const cfg = join(root, "deploy/modules", id, "vercel.json");
  if (!existsSync(dist)) throw new Error(`missing build output ${dist}`);
  if (!existsSync(cfg)) throw new Error(`missing ${cfg}`);
  const out = join(root, ".vercel/output");
  rmSync(out, { recursive: true, force: true });
  mkdirSync(join(out, "static"), { recursive: true });
  cpSync(dist, join(out, "static"), { recursive: true });
  writeFileSync(join(out, "config.json"), JSON.stringify(toConfig(JSON.parse(readFileSync(cfg, "utf8"))), null, 2));
  return out;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const out = run((process.env.VITE_MODULE ?? "").trim().toLowerCase());
  console.log(`[vercel-module-output] wrote ${out}`);
}
